package com.onlineassessment.controller; import com.onlineassessment.dto.*; import com.onlineassessment.service.ResultService; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/assessments") @RequiredArgsConstructor public class LeaderboardController {final ResultService results; @GetMapping("/{id}/leaderboard") ApiResponse<?> leaderboard(@PathVariable Long id){return ApiResponse.ok("Leaderboard",results.leaderboard(id));} }
